<x-app-layout :receipt="true" :title="$return->return_number"><section data-print-page class="mx-auto max-w-3xl bg-white p-8"><x-receipt-letterhead document="Return Receipt" /><p>{{ $return->return_number }} · Sale {{ $return->sale_number_snapshot }}</p><p>{{ $return->customer_code_snapshot }} · {{ $return->customer_name_snapshot }}</p>@foreach($return->items as $item)<p class="mt-3">{{ $item->product_name_snapshot }} · {{ \App\Support\Quantity::trim($item->quantity_returned) }} {{ $item->unit_snapshot }} · ₦{{ \App\Support\Money::format($item->return_line_value) }}{{ bccomp((string) ($item->discount_share ?? '0.00'), '0.00', 2) > 0 ? ' after discount' : '' }}</p>@endforeach{{-- The value of the returned goods, then where it went: first against what the customer still owed, and only the rest as credit that can be refunded. A customer who never paid is not shown a refund. --}}<dl class="mt-5 space-y-1"><div class="flex justify-between font-bold"><dt>Returned value</dt><dd>₦{{ \App\Support\Money::format($return->merchandise_value) }}</dd></div><div class="flex justify-between"><dt>Reduces balance owed</dt><dd>₦{{ \App\Support\Money::format($return->receivable_reduction) }}</dd></div><div class="flex justify-between"><dt>Refundable credit</dt><dd>₦{{ \App\Support\Money::format($return->refundable_credit_created) }}</dd></div></dl>@if(bccomp((string) $return->refundable_credit_created, '0.00', 2) > 0)<p class="mt-2 text-sm">Refundable credit is paid back separately, as a refund.</p>@elseif(bccomp((string) $return->merchandise_value, '0.00', 2) === 0)<p class="mt-2 text-sm">These goods were fully discounted, so no money changes hands.</p>@endif<p>Recorded by {{ $return->returned_by_name_snapshot }} · {{ $return->returned_at->format('d M Y H:i') }}</p><button type="button" data-print-trigger class="receipt-controls mt-6 rounded bg-blue-700 px-4 py-2 text-white">Print</button><x-receipt-footer /></section></x-app-layout>
